9	/**
10	 * Convert a string into a lowercase, dash-separated URL slug.
11	 * Latin diacritics are folded to their base letters (Crème -> creme).
12	 * Non-decomposable letters (ß, ø, æ, ł) and non-Latin scripts are kept as-is.
13	 * @param {string} str
14	 * @returns {string}
15	 */
16	export function slugify(str) {
